/** The journal tags of the seven applied migrations, in order. */
const FROZEN_TAGS = [
  "0000_neat_the_fallen",
  "0001_violet_pretty_boy",
  "0002_lazy_earthquake",
  "0003_brave_dexter_bennett",
  "0004_massive_ser_duncan",
  "0005_quiet_rogue",
  "0006_goofy_zombie",
];

function readNormalized(path: string): string {
  return readFileSync(path, "utf8").replace(/\r\n/g, "\n");
}

function sha256(text: string): string {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

/** The single `0007_*.sql` migration, or a failure that says what was found instead. */
function migration0007(): { name: string; sql: string } {
  const found = readdirSync(MIGRATIONS).filter((name) => /^0007_.+\.sql$/.test(name));
  if (found.length !== 1) {
    throw new Error(`expected exactly one migrations/0007_*.sql, found ${found.length}`);
  }
  const name = found[0] as string;
  return { name, sql: readNormalized(join(MIGRATIONS, name)) };
}

/** drizzle-kit separates statements with this marker; each statement is trimmed. */
function statementsOf(sql: string): string[] {
  return sql
    .split("--> statement-breakpoint")
    .map((statement) => statement.trim())
    .filter((statement) => statement.length > 0);
}

describe("AC-8 — migration 0007 exists once and was produced by drizzle-kit", () => {
  it("adds exactly one migrations/0007_*.sql", () => {
    const found = readdirSync(MIGRATIONS).filter((name) => /^0007_.+\.sql$/.test(name));
    expect(found).toHaveLength(1);
  });

  it("is recorded in the drizzle journal right after the seven applied migrations", () => {
    const { name } = migration0007();
    const journal = JSON.parse(readFileSync(join(META, "_journal.json"), "utf8")) as {
      entries: Array<{ idx: number; tag: string }>;
    };

    expect(journal.entries.slice(0, 7).map((entry) => entry.tag)).toEqual(FROZEN_TAGS);
    expect(journal.entries[7]).toMatchObject({ idx: 7, tag: name.replace(/\.sql$/, "") });
  });

  it("comes with its drizzle-kit snapshot", () => {
    migration0007();
    expect(existsSync(join(META, "0007_snapshot.json"))).toBe(true);
  });
});

describe("AC-8 — migration 0007 is additive", () => {
  it("holds only CREATE TABLE and CREATE [UNIQUE] INDEX statements", () => {
    const statements = statementsOf(migration0007().sql);

    expect(statements.length).toBeGreaterThan(0);
    for (const statement of statements) {
      expect(statement).toMatch(/^CREATE (TABLE|INDEX|UNIQUE INDEX)\s/i);
    }
  });

  it("creates exactly the events and event_sync_links tables", () => {
    const created = statementsOf(migration0007().sql)
      .map((statement) => /^CREATE TABLE\s+[`"]?(\w+)[`"]?/i.exec(statement)?.[1])
      .filter((table): table is string => table !== undefined);

    expect([...created].sort()).toEqual(EVENT_TABLES);
  });

  it("creates indexes only on those two tables", () => {
    const targets = statementsOf(migration0007().sql)
      .filter((statement) => /^CREATE (UNIQUE )?INDEX\s/i.test(statement))
      .map((statement) => /\bON\s+[`"]?(\w+)[`"]?\s*\(/i.exec(statement)?.[1]);

    expect(targets.length).toBeGreaterThan(0);
    for (const target of targets) {
      expect(EVENT_TABLES).toContain(target);
    }
  });

  it("contains no ALTER, DROP or PRAGMA and no __new_ table rebuild", () => {
    const { sql } = migration0007();

    expect(sql).not.toMatch(/\bALTER\b/i);
    expect(sql).not.toMatch(/\bDROP\b/i);
    expect(sql).not.toMatch(/\bPRAGMA\b/i);
    expect(sql).not.toContain("__new_");
  });
});

describe("AC-8 — migrations 0000 to 0006 are byte-identical to main", () => {
  it.each(FROZEN)("leaves %s untouched", (path, expectedDigest) => {
    expect(sha256(readNormalized(path))).toBe(expectedDigest);
  });
});
